.xt_page_box {
  width: 100%;
  height: calc(100% - 56px);
  overflow: auto;
  // background: red;
  .desk_t {
    display: flex;
    justify-content: space-between;

    .desk_tlt {
      // background: url('../../assets/desk/character.png') no-repeat 100% bottom;
      position: relative;

      .rrr {
        position: absolute;
        bottom: 0;
        right: 0;
      }
    }

    .desk_tl {
      width: 58.5%;
    }

    .desk_tr {
      width: 40%;
    }
  }

  .desk_title {
    color: #192C7D;
    font-weight: 600;
    line-height: 30px;
    display: flex;
    align-items: center;
    margin-bottom: 5px;
    // background: url('../../assets/desk/jiantou.png') no-repeat 100px center;
    img {
      width: 18px;
      height: 18px;
      margin-left: 10px;
    }
  }

  .desk_tabs {
    // background: linear-gradient(230deg, #f0f4ff 0%, #F7FAFF 100%);
    background: #fff;
    border-top-left-radius: 6px;
    border-top-right-radius: 6px;

    ::v-deep .el-tabs__item {
      font-size: 18px;
      color: #666;
      // line-height: 25px;

      span {
        padding: 0 20px;
      }
    }

    ::v-deep .el-tabs__item.is-active {
      font-weight: bold;
      color: #409EFF;
    }

    ::v-deep .el-tabs__header {
      margin-bottom: 0;
    }
  }

  .desk_content {
    overflow: auto;
    ::v-deep .el-radio-group {
      display: flex;
      margin-bottom: 10px;
    }

    ::v-deep .bbt {
      flex: 1;
    }

    ::v-deep .bbt2 {
      flex: none;
    }

    ::v-deep .el-radio-button__inner {
      width: 100%;
      padding: 12px 10px;
    }
  }

  .contents {
    background: #fff;
    padding: 10px;
    border-radius: 6px;
  }

  .desk_ip {
    display: flex;
    background: linear-gradient(180deg, rgba(220, 254, 241, 0.71) 0%, rgba(255, 255, 255, 0.22) 100%);
    padding: 26px 15px;
  }

  .desk_ip_l {
    .desk_ip_total {
      text-align: center;
      border-right: 1px solid #e1e1e1;
      padding-right: 5px;
      margin-top: 15px;

      .zhi1 {
        font-size: 40px;
        font-weight: bold;
        color: #FF6D1A;
        padding-right: 5px;
      }

      .zhi2 {
        font-size: 14px;
        color: #666;
      }
    }
  }

  .desk_ip_r {
    margin-left: 10px;
    flex: 0.9;

    .desk_ip_nei {
      display: flex;

      .desk_ip_nei1 {
        font-size: 12px;
        color: #06AE79;
        text-align: center;
        margin-top: 0px;
        margin-left: 15px;
      }

      .desk_ip_nei11 {
        color: #0D76FB;
      }

      .desk_ip_nei2 {
        display: flex;
        // margin-left: 25px;

        flex: 1;
        justify-content: center;

        .dian {
          width: 8px;
          height: 8px;
          background: #06AE79;
          border-radius: 50%;
          margin-top: 17px;
        }

        .dian2 {
          background: #FE914D;
        }

        .dian3 {
          background: #4D54FE;
        }

        .desk_ip_nei_z1 {
          font-size: 14px;
          color: #666;
          margin: 10px 7px 0 4px;
        }

        .desk_ip_nei_z2 {
          font-size: 24px;
          color: #000;
          font-weight: bold;
        }
      }
    }

    .desk_ip_neit {
      border-bottom: 1px solid #e1e1e1;
      padding-bottom: 12px;
    }

    .desk_ip_neib {
      padding-top: 10px;
    }
  }

  .desk_quick {
    display: flex;
    justify-content: space-between;
    flex-flow: wrap;
    padding-top: 20px;

    .desk_quick_item {
      cursor: pointer;
      font-size: 16px;
      color: #666;
      width: 33%;
      text-align: center;
      margin-bottom: 25px;

      img {
        margin-right: 10px;
        vertical-align: middle;
      }

      &:nth-child(7) {
        margin-bottom: 20px;
      }

      &:nth-child(8) {
        margin-bottom: 20px;
      }

      &:nth-child(9) {
        margin-bottom: 20px;
      }
    }
  }

  .desk_b {
    margin-top: 10px;
    display: flex;
    justify-content: space-between;

    .desk_bl {
      width: 35%;
    }

    .desk_br {
      width: 63.5%;
    }
  }
}
